// Jeden uniwersalny format dla wszystkich sieci: te same pola i kolejność.
function canonicalStoreProduct(product){
  return {
    id:product.id,name:product.name,brand:product.brand||'',category:product.category||'Produkty spożywcze',store:product.store||'Sklep',
    source:product.source||'',sourceKind:product.sourceKind||'',sourceUrl:product.sourceUrl||'',sourceLicense:product.sourceLicense||'',
    kcal100:product.kcal100==null?null:Number(product.kcal100),protein100:product.protein100??null,fat100:product.fat100??null,carbs100:product.carbs100??null,fiber100:product.fiber100??null,
    unitWeight:product.unitWeight??null,aliases:Array.isArray(product.aliases)?product.aliases:[],dataNote:product.dataNote||''
  };
}

