// Oficjalne listy i strony sklepów potwierdzają nazwy oraz występowanie części
// produktów. Makroskładniki w tym katalogu są estymacją kategorii, jeśli źródło
// nie udostępniało kompletnej tabeli konkretnego opakowania.
const retailerSources={
  'Lidl':'https://www.lidl.pl/static/assets/Lista_artykulow_objetych_akcja_Twoje_niskie_ceny-2556388.pdf',
  'Biedronka':'https://zakupy.biedronka.pl/dania-gotowe/',
  'Kaufland':'https://sklep.kaufland.pl/asortyment/produkty-spozywcze.html',
  'Carrefour':'https://www.carrefour.pl/dania-gotowe-i-przystawki/dania-gotowe-i-przystawki-7v'
};
const retailerNote = store => `Nazwa/asortyment przypisane do sieci ${store}; wartości odżywcze są SZACUNKOWE dla typu produktu i nie pochodzą z etykiety tego SKU. Nie traktuj kcal ani makroskładników jako danych producenta. Dostępność i gramatura mogą się różnić; dla zapakowanego produktu nadrzędna jest etykieta.`;
function buildRetailerIndexProducts(sourceProducts, targetCount=750){
  const groups=new Map();
  for(const p of sourceProducts){
    if(!groups.has(p.category)) groups.set(p.category,[]);
    groups.get(p.category).push(p);
  }
  const categories=[...groups.keys()];
  const chosen=[]; let cursor=0;
  while(chosen.length<targetCount && categories.length){
    const cat=categories[cursor%categories.length];
    const list=groups.get(cat); const ix=Math.floor(cursor/categories.length);
    if(ix<list.length) chosen.push(list[ix]);
    cursor++;
    if(cursor>targetCount*categories.length*2) break;
  }
  const out=[];
  for(const store of ['Lidl','Biedronka','Kaufland','Carrefour']){
    for(const p of chosen){
      const id=`catalog-${norm(store)}-${p.id}`;
      const name=`${p.name} — asortyment ${store}`;
      out.push(canonicalStoreProduct({id,name,brand:p.brand||'',category:p.category,store,
        source:`Katalog kategorii / indeks asortymentu ${store}`,sourceKind:'retailer-assortment-reference',
        sourceUrl:retailerSources[store],kcal100:p.kcal100,protein100:p.protein100,fat100:p.fat100,carbs100:p.carbs100,fiber100:p.fiber100,
        unitWeight:p.unitWeight,aliases:[...new Set([...(p.aliases||[]),p.name.toLowerCase(),store.toLowerCase()])],dataNote:retailerNote(store)}));
    }
  }
  return out;
}

